#include "../../src/ArabicShaper.h"
#include <unity.h>

struct Golden {
  const char *in;
  const uint8_t out[32];
  const uint8_t len;
};

// Generated by tools/out/gen_goldens.py (Python reference shaper)
static const Golden GOLDENS[] = {
    {"الله", {0xEE, 0xE1, 0xE0, 0x87}, 4},
    {"لا", {0xF7}, 1},
    {"بسم الله", {0xEE, 0xE1, 0xE0, 0x87, 0x20, 0xE6, 0xB5, 0x98}, 8},
    {"12:30 عدد 15",
     {0x20, 0x31, 0x35, 0x89, 0x8A, 0xCC, 0x31, 0x32, 0x3A, 0x33, 0x30,
      0x20},
     12},
    {"ABC 123", {0x41, 0x42, 0x43, 0x20, 0x31, 0x32, 0x33}, 7},
    {"عيدكم مبارك",
     {0xDB, 0x8D, 0x88, 0x99, 0xE4, 0x20, 0xE6, 0xDC, 0x8A, 0xF1, 0xCC}, 11},
    {"لا إله إلا الله",
     {0xEE, 0xE1, 0xE0, 0x87, 0x20, 0xF7, 0x85, 0x20, 0xEE, 0xE0, 0x85,
      0x20, 0xF7},
     13},
    {"محمد", {0x8A, 0xE5, 0xAD, 0xE4}, 4},
    {"مُحَمَّد", {0x8A, 0xE5, 0xAD, 0xE4}, 4},
    {"الصلاة على النبي",
     {0xF2, 0x99, 0xE9, 0xE0, 0x87, 0x20, 0x94, 0xE1, 0xCC, 0x20, 0x9B,
      0xF8, 0xBD, 0xE0, 0x87},
     15},
};

void setUp() {}
void tearDown() {}

void test_golden_vectors() {
  char out[128];
  for (const auto &g : GOLDENS) {
    size_t n = ArabicShaper::shape(g.in, out, sizeof(out));
    TEST_ASSERT_EQUAL_MESSAGE(g.len, n, g.in);
    TEST_ASSERT_EQUAL_UINT8_ARRAY_MESSAGE(g.out, out, g.len, g.in);
    TEST_ASSERT_EQUAL_CHAR('\0', out[n]);
  }
}

void test_ascii_passthrough() {
  char out[64];
  TEST_ASSERT_EQUAL(7, ArabicShaper::shape("ABC 123", out, sizeof(out)));
  TEST_ASSERT_EQUAL_STRING("ABC 123", out);
}

void test_harakat_dropped() {
  char out[64];
  ArabicShaper::shape("\xD9\x85\xD9\x8F\xD8\xAD\xD9\x8E\xD9\x85\xD9\x91"
                      "\xD8\xAF",
                      out, sizeof(out));
  TEST_ASSERT_EQUAL_STRING("\x8A\xE5\xAD\xE4", out);
}

void test_standalone_hamza_maps_to_font_slot() {
  char out[8];
  size_t n = ArabicShaper::shape(u8"ء", out, sizeof(out));
  TEST_ASSERT_EQUAL_size_t(1, n);
  TEST_ASSERT_EQUAL_UINT8(0x80, static_cast<uint8_t>(out[0]));
}

void test_hamza_in_day_name_is_not_replaced() {
  char out[32];
  size_t n = ArabicShaper::shape(u8"الأربعاء", out, sizeof(out));
  TEST_ASSERT_GREATER_THAN_size_t(0, n);
  TEST_ASSERT_EQUAL_UINT8(0x80, static_cast<uint8_t>(out[0]));
}

void test_buffer_truncation_safe() {
  char out[4];
  size_t n = ArabicShaper::shape("الله الله", out, sizeof(out));
  TEST_ASSERT_LESS_OR_EQUAL_size_t(3, n);
  TEST_ASSERT_EQUAL_CHAR('\0', out[n]);
}

void test_null_and_empty() {
  char out[8];
  TEST_ASSERT_EQUAL(0, ArabicShaper::shape(nullptr, out, sizeof(out)));
  TEST_ASSERT_EQUAL(0, ArabicShaper::shape("", out, sizeof(out)));
  TEST_ASSERT_EQUAL(0, ArabicShaper::shape("ا", out, 0));
}

void test_invalid_utf8_becomes_question() {
  char out[8];
  ArabicShaper::shape("\xFF\xFE", out, sizeof(out));
  TEST_ASSERT_EQUAL_STRING("??", out);
}

void test_preformed_passthrough() {
  // U+FEEA (heh FINAL) = EF BB AA -> its slot directly
  char out[8];
  ArabicShaper::shape("\xEF\xBB\xAA", out, sizeof(out));
  TEST_ASSERT_EQUAL_STRING("\xEE", out);
}

void test_indic_digits_keep_numeric_order() {
  char out[48];
  ArabicShaper::shape(u8"٠١٢٣٤٥٦٧٨٩ ۱۲:۳۰", out, sizeof(out));
  TEST_ASSERT_EQUAL_STRING("0123456789 12:30", out);
}

int main() {
  UNITY_BEGIN();
  RUN_TEST(test_golden_vectors);
  RUN_TEST(test_ascii_passthrough);
  RUN_TEST(test_harakat_dropped);
  RUN_TEST(test_standalone_hamza_maps_to_font_slot);
  RUN_TEST(test_hamza_in_day_name_is_not_replaced);
  RUN_TEST(test_buffer_truncation_safe);
  RUN_TEST(test_null_and_empty);
  RUN_TEST(test_invalid_utf8_becomes_question);
  RUN_TEST(test_preformed_passthrough);
  RUN_TEST(test_indic_digits_keep_numeric_order);
  return UNITY_END();
}
